+        implements InternalAggregatingState<K, N, IN, ACC, OUT> {
+
+    MetricsTrackingAggregatingState(
+            String stateName,
+            InternalAggregatingState<K, N, IN, ACC, OUT> original,
+            LatencyTrackingStateConfig latencyTrackingStateConfig) {
